      if (p.z <= 0.0 || p.x < 0.0 || p.x > 1.0 || p.y < 0.0 || p.y > 1.0) { continue; }
      let seen = lensSees(l, q);
      if (seen <= 0.0) { continue; }
      let away = q - l.o;
      let d2 = max(dot(away, away), 0.01);
      let cookie = textureSampleLevel(inputTexture, inputSampler, p.xy, 0.0).rgb;
      let phase = hg(dot(away * inverseSqrt(d2), -ray), params.anisotropy);
      scatter = scatter + cookie * (params.brightness * l.nominal * l.nominal / d2 * phase * air(q, frameU.absTime) * exp(-params.density * t) * dt);
    }
  }
  scatter = scatter * params.gain;
  return vec4f(scatter, 1.0);
}

parameters.kernel:
// Stage previz — kabuki fly-out (generated by src/projects/stage-previz/document.ts).
struct Params {
  lift: f32, // @default 0  0 = the kabuki hangs in; 1 = flown out to its pipe and parked out of sight.
};

const TOP: f32 = 9.3000;

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let k = smoothstep(0.0, 1.0, clamp(ctx.params.lift, 0.0, 1.0));
  q.position.y = mix(p.position.y, TOP, k) + select(0.0, 80.0, k > 0.999);
  return q;
}

// Stage previz — the projector rig (generated by src/projects/stage-previz/rig.ts from the GLB's parts).
struct Params {
  dsOffset: f32, // @default 0  DS truss offset along z, metres (+ toward the house).
  dsTilt: f32, // @default 25.5609  DS projector tilt, degrees down, about its clamp.
  sideTilt: f32, // @default 36.788  Side projectors' tilt, degrees down, about their lens.
  sideRoll: f32, // @default 90  Side projectors' roll, degrees (stage right +, stage left −): 90 is portrait.
};

const PART_DS_TRUSS: u32 = 1u;
const PART_DS: u32 = 2u;
const PART_SR: u32 = 4u;
const PART_SL: u32 = 3u;
const DS_PIVOT: vec3f = vec3f(0.00000, 9.28000, 1.02180);
const SR_LENS: vec3f = vec3f(-8.15000, 8.55000, 2.31520);
const SL_LENS: vec3f = vec3f(8.15000, 8.55000, 2.31520);
const SR_AXIS: vec3f = vec3f(0.00000, 0.00000, 1.00000);
const SL_AXIS: vec3f = vec3f(0.00000, 0.00000, -1.00000);
const SR_FWD: vec3f = vec3f(0.80086, -0.59886, -0.00000);
const SL_FWD: vec3f = vec3f(-0.80086, -0.59886, -0.00000);
const SIDE_REST: f32 = 36.78796;

// Rodrigues: v turned by angle about a unit axis.
fn turn(v: vec3f, axis: vec3f, angle: f32) -> vec3f {
  let c = cos(angle);
  return v * c + cross(axis, v) * sin(angle) + axis * dot(axis, v) * (1.0 - c);
}

// Pitch down by t about +x, for the DS body built level and facing −z: (0,0,−1) → (0,−sin t,−cos t).
// rig.ts's projDS expressions turn the lens offset by exactly this.
fn pitch(v: vec3f, t: f32) -> vec3f {
  let c = cos(t);
  let s = sin(t);
  return vec3f(v.x, v.y * c + v.z * s, -v.y * s + v.z * c);
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let part = u32(round(p.surface.w));
  if (part == PART_DS) {
    let t = radians(ctx.params.dsTilt);
    q.position = DS_PIVOT + pitch(p.position - DS_PIVOT, t);
    q.normal = pitch(p.normal, t);
  } else if (part == PART_SR || part == PART_SL) {
    let lens = select(SL_LENS, SR_LENS, part == PART_SR);
    let axis = select(SL_AXIS, SR_AXIS, part == PART_SR);
    let fwd = select(SL_FWD, SR_FWD, part == PART_SR);
    // The roll first, about the rest optical axis, by −roll — exactly how the Projector node
    // turns its own up vector (camera.ts guardedRolledUp) — so the body hangs as it throws.
    let roll = -radians(select(-ctx.params.sideRoll, ctx.params.sideRoll, part == PART_SR));
    // Then the tilt: turning about the right vector by +a lifts the nose, so down is −a.
    let down = -radians(max(ctx.params.sideTilt, 5.0) - SIDE_REST);
    q.position = lens + turn(turn(p.position - lens, fwd, roll), axis, down);
    q.normal = turn(turn(p.normal, fwd, roll), axis, down);
  }
  if (part == PART_DS || part == PART_DS_TRUSS) {
    q.position.z = q.position.z + ctx.params.dsOffset;
  }
  return q;
}

// Stage previz — talent stand-ins on or off (generated by src/projects/stage-previz/document.ts).
struct Params {
  show: f32, // @default 1  1 shows the two dancers and the vocalist; 0 parks them under the floor.
};

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  q.position.y = p.position.y - select(200.0, 0.0, ctx.params.show > 0.5);
  return q;
}

parameters.source:
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// Stage previz — beam test content (generated by src/projects/stage-previz/test-content.ts).
struct Params {
  look: f32, // @default -1  -1 cycles the four looks; 0 wash, 1 spokes, 2 sweep, 3 rings holds one.
  hold: f32, // @default 8  Seconds per look while cycling.
  hue: f32, // @default 0  Shifts the palette (0..1 around the wheel).
  level: f32, // @default 1  Overall brightness.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn palette(t: f32) -> vec3f {
  return 0.5 + 0.5 * cos(6.2831853 * (t + params.hue + vec3f(0.0, 0.33, 0.67)));
}

fn showLook(index: i32, uv: vec2f, t: f32) -> vec3f {
  let size = vec2f(textureDimensions(inputTexture));
  let p = (uv - 0.5) * vec2f(size.x / max(size.y, 1.0), 1.0);
  switch index {
    case 0: {
      return palette(t * 0.05) * (0.55 + 0.45 * sin(t * 2.2));
    }
    case 1: {
      let a = atan2(p.y, p.x) / 6.2831853;
      let spokes = smoothstep(0.32, 0.5, abs(fract(a * 9.0 + t * 0.08) - 0.5) * 2.0);
      return palette(0.6 + t * 0.03) * spokes * smoothstep(0.02, 0.08, length(p));
    }
    case 2: {
      let bar = smoothstep(0.62, 0.9, abs(fract(uv.x * 2.5 - t * 0.45) - 0.5) * 2.0);
      return mix(vec3f(1.0), palette(0.15), 0.35) * bar;
    }
    default: {
      let ring = smoothstep(0.55, 0.95, abs(fract(length(p) * 3.5 - t * 0.6) - 0.5) * 2.0);
      return palette(0.85 + length(p) * 0.3) * ring;
    }
  }
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let keep = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let t = frameU.absTime;
  var c: vec3f;
  if (params.look >= 0.0) {
    c = showLook(i32(params.look) % 4, uv, t);
  } else {
    let hold = max(params.hold, 1.0);
    let phase = t / hold;
    let index = i32(floor(phase)) % 4;
    let blend = smoothstep(hold - 1.0, hold, fract(phase) * hold);
    c = mix(showLook(index, uv, t), showLook((index + 1) % 4, uv, t), blend);
  }
  return vec4f(c * params.level + keep, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// Stage previz — FX feed test content (generated by src/projects/stage-previz/test-content.ts).
struct Params {
  speed: f32, // @default 0.25  Cycles per second.
  level: f32, // @default 1  Overall brightness.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn hue(h: f32) -> vec3f {
  return clamp(abs(fract(h + vec3f(0.0, 0.6666667, 0.3333333)) * 6.0 - 3.0) - 1.0, vec3f(0.0), vec3f(1.0));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let keep = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let t = frameU.time * params.speed;
  var c = vec3f(0.0);
  if (uv.y < 0.5) {
    let up = 1.0 - uv.y * 2.0;                      // 0 at the lowest rack row, 1 at the top truss row
    let band = 1.0 - smoothstep(0.0, 0.16, abs(fract(t * 0.5) - up));
    c = hue(fract(uv.x * 0.8 - t)) * (0.3 + 0.7 * band);
  } else {
    let upstage = 1.0 - (uv.y - 0.5) * 2.0;         // 0 at the downstage edge, 1 at the riser's back
    let phase = fract(t - uv.x * 0.7 - upstage * 0.3);
    let flash = select(0.0, 1.0, phase < 0.06);
    c = hue(fract(t * 0.3 + upstage * 0.25)) * 0.22 + vec3f(flash);
  }
  return vec4f(c * params.level + keep, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// Stage previz — alignment grid (generated by src/projects/stage-previz/test-content.ts).
struct Params {
  cells: f32, // @default 16  Grid cells across the width.
  level: f32, // @default 1  Line brightness.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn line(d: f32, width: f32) -> f32 {
  return 1.0 - smoothstep(width * 0.5, width * 0.5 + 1.0, d);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let keep = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0 + frameU.time * 0.0;
  let size = vec2f(textureDimensions(inputTexture));
  let px = uv * size;
  let cell = size.x / max(params.cells, 1.0);
  let g = abs(px - cell * round(px / cell));
  var c = vec3f(0.0);
  c = max(c, vec3f(0.55) * line(min(g.x, g.y), 2.0));
  let centre = abs(px - size * 0.5);
  c = max(c, vec3f(1.0) * line(min(centre.x, centre.y), 6.0));
  let edge = min(min(px.x, size.x - px.x), min(px.y, size.y - px.y));
  c = max(c, vec3f(1.0) * line(edge, 12.0));
  let r = length(px - size * 0.5);
  c = max(c, vec3f(1.0) * line(abs(r - size.y * 0.46), 5.0));
  let corner = size.y * 0.16;
  if (px.x < corner && px.y < corner) { c = vec3f(1.0, 0.1, 0.1); }
  if (px.x > size.x - corner && px.y < corner) { c = vec3f(0.1, 1.0, 0.2); }
  if (px.x < corner && px.y > size.y - corner) { c = vec3f(0.15, 0.3, 1.0); }
  if (px.x > size.x - corner && px.y > size.y - corner) { c = vec3f(1.0, 0.9, 0.1); }
  return vec4f(c * params.level + keep, 1.0);
}
